CREATE TABLE IF NOT EXISTS crew_payroll_slips (id TEXT PRIMARY KEY, crew TEXT NOT NULL, period_month TEXT NOT NULL, base_pay INTEGER NOT NULL DEFAULT 0, extra_total INTEGER NOT NULL DEFAULT 0, total_pay INTEGER NOT NULL DEFAULT 0, data_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN ('submitted', 'paid')), submitted_by TEXT NOT NULL DEFAULT '', submitted_at TEXT NOT NULL, updated_at TEXT NOT NULL, paid_at TEXT, UNIQUE (crew, period_month));
